/* Review prototype only: no API calls, no actual Agent execution. */
const $ = (id) => document.getElementById(id)
const names = {codex:'Codex',trae:'TRAE',cursor:'Cursor'}
const catalog = window.MODEL_SNAPSHOT
const storageKey = 'jarvis.chat-design.v1'
const esc = (s) => String(s ?? '').replace(/[&<>"']/g, c => ({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]))
const uid = () => crypto.randomUUID()
const files = new Map()
const runs = new Map()
const sources = ['Jarvis 项目','BAX 反馈群 · 最近 7 天','本周任务','产品方案文档']
let archived = false, pickerKind = '', showAll = false, pendingAgent = null, toastTimer
let state
function blank(agent='codex',model=catalog[agent][0].id) { return {id:uid(),title:'新对话',agent,model,draft:'',sources:[],attachments:[],messages:[],updated:Date.now(),effort:'medium'} }
function seed(){const s=blank();s.title='把 Jarvis 的对话升级为第一屏';s.sources=['Jarvis 项目'];s.messages=[{id:uid(),role:'user',text:'我们把右下角的对话升级成第一个 Tab，支持多个会话、选 Agent 和模型，以及图片和文件。先把完整体验设计好。',attachments:[]},{id:uid(),role:'assistant',agent:'codex',model:catalog.codex[0].id,text:'建议把对话作为默认首页，让每次讨论都可以继续。\n\n左侧管理会话，中央专注内容，输入区直接选择数据来源、Agent 和模型。会话与草稿独立保存，切换页面也不会打断工作。\n\n模型优先展示 5 个，支持搜索源头提供的全部选项。有历史时切换 Agent，可以携带记录新开会话，原会话保留。\n\n图片可上传、粘贴和预览，生成的材料直接以文件卡片交付。\n\n这是一段设计演示回复，没有调用真实 Agent。',attachments:[],activity:true}];return {sessions:[s],active:s.id}}
try{state=JSON.parse(localStorage.getItem(storageKey))||seed();if(!Array.isArray(state.sessions)||!state.sessions.length)state=seed()}catch{state=seed()}
for(const s of state.sessions)for(const m of s.messages)if(m.running){m.running=false;m.text+='\n\n演示已中断：页面重新加载。'}
if(!state.sessions.some(s=>s.id===state.active))state.active=state.sessions[0].id
function current(){return state.sessions.find(s=>s.id===state.active)}
function save(){try{localStorage.setItem(storageKey,JSON.stringify(state))}catch{toast('浏览器存储不可用；本次演示记录仅保留在当前页面。')}}
function toast(s){$('toast').textContent=s;$('toast').hidden=false;clearTimeout(toastTimer);toastTimer=setTimeout(()=>$('toast').hidden=true,3300)}
function fileHTML(a){const f=files.get(a.id);return `<button type="button" class="file-card" data-file="${a.id}">${f?.url&&a.type.startsWith('image/')?`<img src="${f.url}" alt="${esc(a.name)}">`:'<span class="file-icon">▧</span>'}<span>${esc(a.name)}<small>${Math.max(1,Math.round(a.size/1024))} KB · ${f?'预览 / 下载':'需要重新添加'}</small></span></button>`}
function renderList(){const q=$('search').value.trim().toLowerCase();const list=state.sessions.filter(s=>!!s.archived===archived&&(!q||[s.title,...s.messages.map(m=>m.text)].join('\n').toLowerCase().includes(q))).sort((a,b)=>b.updated-a.updated);$('sessionList').innerHTML=`<div class="group-label">${archived?'已归档':'最近会话'}</div>`+(list.map(s=>`<button class="session ${s.id===state.active?'selected':''}" data-session="${s.id}"><strong>${esc(s.title)}</strong><span class="blurb">${esc(s.messages.at(-1)?.text||s.draft||'开始一个新的讨论')}</span><small><span>${names[s.agent]} ${runs.has(s.id)?'· 正在回复':''}</span><span>${new Date(s.updated).toLocaleDateString('zh-CN',{month:'numeric',day:'numeric'})}</span></small></button>`).join('')||'<div class="empty-list">没有匹配的会话</div>');$('archives').textContent=archived?'返回最近会话':'查看已归档会话'}
function renderMessages(force=false){const s=current(),box=$('conversation');const near=box.scrollHeight-box.scrollTop-box.clientHeight<100;const welcome=`<div class="welcome"><span class="spark">✳</span><h1>今天想一起推进什么？</h1><p>从一个问题、一份资料，或者一个想做成的结果开始。</p><div class="suggestions"><button data-suggestion="帮我梳理本周最值得推进的三件事"><b>看清进展</b>今天先做什么？</button><button data-suggestion="帮我阅读这份材料，提炼结论和疑问"><b>理解材料</b>从资料里找到答案</button><button data-suggestion="帮我把这个想法整理成可执行的方案"><b>推进事情</b>把想法变成行动</button></div></div>`;$('messages').innerHTML=s.messages.length?s.messages.map(m=>`<article class="message ${m.role}">${m.role==='assistant'?`<div class="assistant-head"><span class="avatar">J</span>Jarvis <small>${names[m.agent]} · ${esc(m.model)} · 演示</small></div>${m.activity?'<details class="activity"><summary>已完成资料检查 · 演示活动</summary><p>整理所选来源 → 比较交互方案 → 输出建议。未执行真实工具。</p></details>':''}`:''}<div class="body">${esc(m.text||'正在整理思路…')}</div>${(m.attachments||[]).map(fileHTML).join('')}${m.role==='assistant'?`<div class="message-tools"><button data-copy="${m.id}">复制回复</button>${m.running?'<span class="subtle">正在回复…</span>':''}</div>`:''}</article>`).join(''):welcome;if(force||near){box.scrollTop=box.scrollHeight;$('jump').hidden=true}else if(runs.has(s.id))$('jump').hidden=false}
function renderComposer(){const s=current(),running=runs.has(s.id);$('input').value=s.draft;$('agent').innerHTML=`<span class="dot"></span>${names[s.agent]} ⌄`;const m=catalog[s.agent].find(m=>m.id===s.model);$('model').textContent=`${m?.name||s.model} ⌄`;$('effort').hidden=!m?.efforts.length;$('effort').textContent=`${s.effort} ⌄`;$('sourceChips').innerHTML=s.sources.map((v,i)=>`<span class="chip">◎ ${esc(v)}<button type="button" data-remove-source="${i}" aria-label="移除 ${esc(v)}">×</button></span>`).join('');$('attachments').innerHTML=s.attachments.map(a=>`<div style="position:relative">${fileHTML(a)}<button type="button" class="remove-file" data-remove-file="${a.id}" aria-label="移除 ${esc(a.name)}">×</button></div>`).join('');$('send').textContent=running?'■':'↑';$('send').classList.toggle('stop',running);$('send').setAttribute('aria-label',running?'停止生成':'发送消息');$('send').disabled=!running&&!s.draft.trim()&&!s.attachments.length;$('hint').textContent=running?'正在生成演示回复 · 可以继续写草稿或切换会话':'Enter 发送 · Shift + Enter 换行 · 可粘贴或拖入图片';$('branchNote').hidden=!s.origin;$('branchNote').textContent=s.origin?`↳ 从「${s.origin}」携带记录继续 · 已新建 ${names[s.agent]} 会话`:''}
function render(){const s=current();$('title').textContent=s.title;$('subtitle').textContent=s.sources.length?'优先参考 '+s.sources.join('、'):'自动参考工作上下文';renderList();renderMessages(true);renderComposer();save();history.replaceState(null,'','#session='+s.id)}
function select(id){state.active=id;document.querySelector('.history').classList.remove('open');render()}
function newSession(){const s=blank(current().agent,current().model);state.sessions.unshift(s);state.active=s.id;archived=false;render();$('input').focus()}
function openPicker(kind){pickerKind=kind;showAll=false;$('pickerSearch').value='';drawPicker();$('picker').showModal()}
function closePicker(){$('picker').close()}
function optionsHTML(rows,selected){return rows.map(r=>`<button class="option ${r.id===selected?'chosen':''}" data-option="${esc(r.id)}"><span><strong>${esc(r.name)}</strong><small>${esc(r.note||'')}</small></span>${r.id===selected?'<span class="check">✓</span>':''}</button>`).join('')}
function drawPicker(){const s=current();$('pickerSearch').hidden=pickerKind!=='model';$('pickerFooter').innerHTML='';if(pickerKind==='agent'){$('pickerTitle').textContent='选择底层 Agent';$('pickerNote').textContent='三种执行来源 · 本原型只演示选择，不启动 Agent';$('pickerItems').innerHTML=optionsHTML(Object.entries(names).map(([id,name])=>({id,name,note:`本机已发现模型目录 · ${catalog[id].length} 个选项`})),s.agent)}else if(pickerKind==='model'){const q=$('pickerSearch').value.toLowerCase(),all=catalog[s.agent].filter(m=>[m.id,m.name].join(' ').toLowerCase().includes(q)),shown=q||showAll?all:all.slice(0,5);$('pickerTitle').textContent=`${names[s.agent]} 模型`;$('pickerNote').textContent='2026-09-10 本机发现快照 · 无发布日期，按源头顺序展示';$('pickerItems').innerHTML='<div class="section-label">'+(q?'搜索结果':showAll?'全部模型':'推荐浏览 · 前 5 个')+'</div>'+optionsHTML(shown.map(m=>({...m,note:`${m.id} · ${m.image===true?'支持图片':m.image===false?'文字输入':'图片能力待验证'}`})),s.model);if(!shown.length)$('pickerItems').innerHTML='<p class="subtle">未找到模型，试试其他关键词。</p>';if(!q&&!showAll&&all.length>5)$('pickerFooter').innerHTML=`<button class="quiet" id="allModels">查看全部 ${all.length} 个模型 ↓</button>`}else if(pickerKind==='sources'){$('pickerTitle').textContent='选择数据来源';$('pickerNote').textContent='优先参考这些资料，必要时补充查证。以下为演示资料。';$('pickerItems').innerHTML=optionsHTML(sources.map((name,i)=>({id:String(i),name,note:s.sources.includes(name)?'已加入本会话':'点击加入本会话'})),'');$('pickerFooter').innerHTML='<button class="dialog-action" id="doneSources">完成</button>'}else if(pickerKind==='effort'){$('pickerTitle').textContent='思考强度';$('pickerNote').textContent='只展示所选模型实际返回的选项';$('pickerItems').innerHTML=optionsHTML(catalog[s.agent].find(m=>m.id===s.model).efforts.map(id=>({id,name:id})),s.effort)}else if(pickerKind==='transfer'){$('pickerTitle').textContent=`切换到 ${names[pendingAgent]}`;$('pickerNote').textContent='跨 Agent 将新开会话。携带可见消息和附件引用；原生执行状态不会转移。';$('pickerItems').innerHTML=optionsHTML([{id:'carry',name:'携带记录新建',note:'保留完整可见历史，原会话保持不变'},{id:'empty',name:'空白新建',note:'从新的问题开始'}],'')}else if(pickerKind==='more'){$('pickerTitle').textContent='会话操作';$('pickerNote').textContent='演示数据保存在当前浏览器';$('pickerItems').innerHTML=optionsHTML([{id:'rename',name:'修改标题',note:'在页面标题内编辑'},{id:'archive',name:s.archived?'恢复会话':'归档会话',note:'保留历史和文件引用'}],'')}}
$('pickerItems').onclick=e=>{const b=e.target.closest('[data-option]');if(!b)return;const v=b.dataset.option,s=current();if(pickerKind==='agent'){if(v===s.agent)return closePicker();if(runs.has(s.id)){toast('请先停止当前回复，再切换 Agent。');return}if(s.messages.length){pendingAgent=v;pickerKind='transfer';return drawPicker()}s.agent=v;s.model=catalog[v][0].id}else if(pickerKind==='model'){s.model=v;const m=catalog[s.agent].find(m=>m.id===v);if(!m.efforts.includes(s.effort))s.effort=m.efforts[0]||'';toast('模型选择对下一轮生效。')}else if(pickerKind==='sources'){const source=sources[Number(v)];s.sources=s.sources.includes(source)?s.sources.filter(x=>x!==source):[...s.sources,source];renderComposer();save();return drawPicker()}else if(pickerKind==='effort')s.effort=v;else if(pickerKind==='transfer'){const next=blank(pendingAgent);if(v==='carry'){next.title=s.title+' · 继续';next.messages=structuredClone(s.messages);next.sources=[...s.sources];next.origin=s.title;next.draft=s.draft;next.attachments=structuredClone(s.attachments)}state.sessions.unshift(next);state.active=next.id;archived=false}else if(pickerKind==='more'){closePicker();if(v==='rename')return rename();s.archived=!s.archived;archived=!!s.archived}closePicker();render()}
$('pickerFooter').onclick=e=>{if(e.target.id==='allModels'){showAll=true;drawPicker()}if(e.target.id==='doneSources'){closePicker();render()}}
function rename(){const s=current(),field=document.createElement('input');field.value=s.title;field.setAttribute('aria-label','会话标题');$('title').replaceChildren(field);field.focus();field.select();let done=false;const finish=(keep)=>{if(done)return;done=true;if(keep&&field.value.trim())s.title=field.value.trim();render()};field.onkeydown=e=>{e.stopPropagation();if(e.key==='Enter')finish(true);if(e.key==='Escape')finish(false)};field.onblur=()=>finish(true)}
function addFiles(list){const s=current();for(const file of list){if(s.attachments.length>=10){toast('每条消息最多 10 个文件。');break}if(file.size>25*1024*1024||s.attachments.reduce((n,a)=>n+a.size,0)+file.size>100*1024*1024){toast('单文件上限 25 MiB，每条消息总计 100 MiB。');continue}const a={id:uid(),name:file.name,type:file.type||'application/octet-stream',size:file.size};files.set(a.id,{blob:file,url:URL.createObjectURL(file)});s.attachments.push(a)}renderComposer();save()}
function download(blob,name){const url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(url),30000)}
function preview(id){const a=state.sessions.flatMap(s=>[...s.attachments,...s.messages.flatMap(m=>m.attachments||[])]).find(a=>a.id===id);if(!a)return;const f=files.get(id);$('previewTitle').textContent=a.name;$('previewBody').innerHTML=f?`${a.type.startsWith('image/')?`<img src="${f.url}" alt="${esc(a.name)}">`:'<p>此格式提供原件下载。正式版由 Agent 按需读取。</p>'}<button class="dialog-action" id="downloadFile">↓ 下载原件</button>`:'<p>演示文件只保存在当前页面内存，刷新后需要重新添加。正式版附件会保存到服务端。</p>';if(f)$('downloadFile').onclick=()=>download(f.blob,a.name);$('preview').showModal()}
function stop(){const s=current(),run=runs.get(s.id);if(!run)return;clearInterval(run.timer);run.message.running=false;run.message.text+='\n\n已停止演示生成，保留当前内容。';runs.delete(s.id);renderMessages();renderComposer();renderList();save()}
function send(){const s=current();if(runs.has(s.id))return stop();if(!s.draft.trim()&&!s.attachments.length)return;const m=catalog[s.agent].find(m=>m.id===s.model);if(s.attachments.some(a=>a.type.startsWith('image/'))&&m.image!==true){toast(m.image===false?'所选模型只支持文字，请选择支持图片的模型。':'此 Agent 的图片能力尚未验证，请选择已确认支持图片的组合。');return}if(s.attachments.some(a=>!files.has(a.id))){toast('请移除不可用的演示附件，或重新添加文件。');return}const input=s.draft.trim();if(s.title==='新对话')s.title=(input||s.attachments[0].name).slice(0,28);s.messages.push({id:uid(),role:'user',text:input,attachments:s.attachments});s.attachments=[];s.draft='';s.updated=Date.now();const response={id:uid(),role:'assistant',agent:s.agent,model:s.model,text:'',attachments:[],running:true};s.messages.push(response);const text=`这是一段交互演示回复，没有调用真实 Agent，也没有分析附件内容。\n\n这轮已选择 ${names[s.agent]} / ${s.model}，${s.sources.length?'优先参考 '+s.sources.join('、'):'使用自动工作上下文'}。\n\n正式版会在这里展示有来源的回答、工具执行进度与真实产物。你可以继续切换会话，或点击停止；输入区的下一条草稿会独立保留。\n\n下方提供一份可下载的演示 Markdown，展示从回复到文件交付的完整操作。`;const pieces=Array.from(text);let n=0;const run={message:response};runs.set(s.id,run);render();run.timer=setInterval(()=>{n+=8;response.text=pieces.slice(0,n).join('');if(n>=pieces.length){clearInterval(run.timer);response.running=false;response.activity=true;runs.delete(s.id);const blob=new Blob(['# 对话工作区 · 演示交付\n\n此文件仅用于验证原型的下载交互。\n\n'+text],{type:'text/markdown'}),a={id:uid(),name:'对话工作区-演示说明.md',type:'text/markdown',size:blob.size};files.set(a.id,{blob,url:URL.createObjectURL(blob)});response.attachments.push(a)}if(state.active===s.id){renderMessages();if(!response.running)renderComposer()}renderList();save()},65)}
$('composer').onsubmit=e=>{e.preventDefault();send()}
$('input').oninput=e=>{const s=current();s.draft=e.target.value;$('send').disabled=!runs.has(s.id)&&!s.draft.trim()&&!s.attachments.length;e.target.style.height='auto';e.target.style.height=Math.min(e.target.scrollHeight,180)+'px';save()}
$('input').onkeydown=e=>{if(e.key==='Enter'&&!e.shiftKey&&!e.isComposing){e.preventDefault();if(!runs.has(current().id))send()}}
$('input').onpaste=e=>{const fs=[...e.clipboardData.files];if(fs.length){e.preventDefault();addFiles(fs)}}
$('composer').ondragover=e=>{e.preventDefault();$('composer').classList.add('dragging')}
$('composer').ondragleave=()=>$('composer').classList.remove('dragging')
$('composer').ondrop=e=>{e.preventDefault();$('composer').classList.remove('dragging');addFiles([...e.dataTransfer.files])}
$('upload').onclick=()=>$('fileInput').click();$('fileInput').onchange=e=>{addFiles([...e.target.files]);e.target.value=''}
$('newSession').onclick=newSession;$('search').oninput=renderList;$('archives').onclick=()=>{archived=!archived;renderList()}
$('sources').onclick=()=>openPicker('sources');$('agent').onclick=()=>openPicker('agent');$('model').onclick=()=>openPicker('model');$('effort').onclick=()=>openPicker('effort');$('more').onclick=()=>openPicker('more')
$('closePicker').onclick=closePicker;$('closePreview').onclick=()=>$('preview').close();$('pickerSearch').oninput=drawPicker
$('title').onclick=e=>{if(e.target.tagName!=='INPUT')rename()};$('title').onkeydown=e=>{if(e.key==='Enter')rename()}
$('showHistory').onclick=()=>document.querySelector('.history').classList.add('open');$('hideHistory').onclick=()=>document.querySelector('.history').classList.remove('open')
$('jump').onclick=()=>{$('conversation').scrollTop=$('conversation').scrollHeight;$('jump').hidden=true}
$('export').onclick=()=>{const s=current(),md='# '+s.title+'\n\n> 设计演示会话，非真实 Agent 结果。\n\n'+s.messages.map(m=>'## '+(m.role==='user'?'用户':`Jarvis · ${names[m.agent]} · ${m.model}`)+'\n\n'+m.text+'\n\n'+(m.attachments||[]).map(a=>`附件：${a.name}（文件单独下载）`).join('\n')).join('\n\n');download(new Blob([md],{type:'text/markdown'}),s.title.replace(/[\\/:*?"<>|]/g,'-')+'.md')}
document.onclick=async e=>{const session=e.target.closest('[data-session]');if(session)select(session.dataset.session);const file=e.target.closest('[data-file]');if(file)preview(file.dataset.file);const remove=e.target.closest('[data-remove-file]');if(remove){current().attachments=current().attachments.filter(a=>a.id!==remove.dataset.removeFile);renderComposer();save()}const source=e.target.closest('[data-remove-source]');if(source){current().sources.splice(Number(source.dataset.removeSource),1);renderComposer();save()}const suggestion=e.target.closest('[data-suggestion]');if(suggestion){current().draft=suggestion.dataset.suggestion;renderComposer();save();$('input').focus()}const copy=e.target.closest('[data-copy]');if(copy){const m=current().messages.find(m=>m.id===copy.dataset.copy);try{await navigator.clipboard.writeText(m.text);toast('已复制回复')}catch{toast('浏览器无法访问剪贴板，请手动选择文字复制。')}}const page=e.target.closest('[data-page]');if(page&&page.dataset.page!=='对话')toast('这是对话工作区原型；其他导航沿用现有产品。')}
document.onkeydown=e=>{if((e.metaKey||e.ctrlKey)&&e.key.toLowerCase()==='k'){e.preventDefault();if(!$('picker').open&&!$('preview').open)newSession()}if(e.key==='Escape')document.querySelector('.history').classList.remove('open')}
window.addEventListener('beforeunload',save)
const hash=new URLSearchParams(location.hash.slice(1)).get('session');if(state.sessions.some(s=>s.id===hash))state.active=hash
render()
